class Solution {
public:
    int numberOfBoomerangs(vector<vector<int>>& points) {
        int total = 0;
        for (int i = 0; i < (int)points.size(); i++) {
            map<int, int> dist;
            for (int j = 0; j < (int)points.size(); j++) {
                int dx = points[i][0] - points[j][0], dy = points[i][1] - points[j][1];
                dist[dx * dx + dy * dy]++;
            }
            for (auto& [d, c] : dist) total += c * (c - 1);
        }
        return total;
    }
};
